-- ─────────────────────────────────────────────────────────────────────────────
-- Seed reverse-engineered DERIVATIONS for the ESABCC report indicators into
-- pw_indicator_sheets.layout (the per-indicator calc space).
--
-- Each layout is a year-indexed grid: Year | Value | helper columns. The Value
-- column carries a free-form formula documenting how the published figure is
-- derived from raw inputs (e.g. raw Eurostat Mtoe × 11.63 → TWh). Helper
-- columns hold those raw inputs with per-column `source`. Reproduced from the
-- chapter workbooks (Ch3–Ch9) and verified against the report's published
-- "underlying data" figures by scripts/esabcc-indicator-derivations.
--
-- Drop in next year's raw data (helper columns) and the indicator recomputes.
-- Companion to 041_seed_esabcc_report_indicators.sql. Idempotent.
-- ─────────────────────────────────────────────────────────────────────────────

insert into public.pw_indicator_sheets (indicator_id, layout)
values
  ('esabcc-o1-ghg-total', '{"columns":[{"header":"Value","source":"EEA GHG data viewer","formula":{"expr":"([International aviation]+[Energy supply]+[Industry]+[Transport]+[Buildings and agriculture energy]+[Agriculture (non-energy)]+[LULUCF]+[Waste and other sectors])+[International maritime]*(0.6374552000704592)"}},{"header":"International aviation","source":"EEA GHG data viewer","formula":{"expr":"[1.D.1.a - International Aviation]/1000"}},{"header":"Energy supply","source":"EEA GHG data viewer","formula":{"expr":"([1.A.1 - Energy Industries]+[1.B - Fugitive Emissions from Fuels])/1000"}},{"header":"Industry","source":"EEA GHG data viewer","formula":{"expr":"([1.A.2 - Manufacturing Industries and Construction]+[2 - Industrial Processes and Product Use])/1000"}},{"header":"Transport","source":"EEA GHG data viewer","formula":{"expr":"([1.A.3 - Transport])/1000"}},{"header":"Buildings and agriculture energy","source":"EEA GHG data viewer","formula":{"expr":"[1.A.4 - Other Sectors]/1000"}},{"header":"Agriculture (non-energy)","source":"EEA GHG data viewer","formula":{"expr":"[3 - Agriculture]/1000"}},{"header":"LULUCF","source":"EEA GHG data viewer","formula":{"expr":"[4 - Land Use, Land-Use Change and Forestry]/1000"}},{"header":"Waste and other sectors","source":"EEA GHG data viewer","formula":{"expr":"[Total net emissions (UNFCCC)]/1000-[LULUCF]-[Agriculture (non-energy)]-[Buildings and agriculture energy]-[Transport]-[Industry]-[Energy supply]"}},{"header":"International maritime","source":"EEA GHG data viewer","formula":{"expr":"[1.D.1.b - International Navigation]/1000"}},{"header":"1.D.1.a - International Aviation","source":"EEA GHG data viewer"},{"header":"1.A.1 - Energy Industries","source":"EEA GHG data viewer"},{"header":"1.B - Fugitive Emissions from Fuels","source":"EEA GHG data viewer"},{"header":"1.A.2 - Manufacturing Industries and Construction","source":"EEA GHG data viewer"},{"header":"2 - Industrial Processes and Product Use","source":"EEA GHG data